def shortest_path(graph, source, target):
    # Set up initial conditions
    distance = {source: 0}
    prev_node = {source: None}
    unvisited = list(graph.keys())
    visited = []

    # Until we're done
    while unvisited:
        # Find the closest node that hasn't been visited yet
        closest = None
        for node in unvisited:
            if node in visited:
                continue
            if closest is None:
                closest = node
            elif distance[node] < distance[closest]:
                closest = node

        # If we found a target node, stop
        if closest == target:
            break

        # Otherwise, we've visited this node
        visited.append(closest)
        unvisited.remove(closest)

        # Add the neighbors of this node to the priority queue
        for neighbor, weight in graph.get(closest, []):
            if neighbor in visited:
                continue
            distance_to_neighbor = distance[closest] + weight
            if neighbor not in distance or distance_to_neighbor < distance[neighbor]:
                distance[neighbor] = distance_to_neighbor
                prev_node[neighbor] = closest

    # If we visited all nodes and still haven't found the target, the target is unreachable
    if target not in distance:
        return float("inf"), None

    # Reconstruct the path
    path = [target]
    while path[-1] != source:
        path.append(prev_node[path[-1]])
    path.reverse()

    return distance[target], path
