    # Initialize the distance and path dictionaries
    distance = {node: float('inf') for node in graph}
    distance[source] = 0
    path = {node: None for node in graph}

    # Priority queue to hold the nodes to be visited
    from collections import deque
    queue = deque([source])

    while queue:
        current = queue.popleft()

        # If we have reached the target, reconstruct the path
        if current == target:
            path_tuple = [target]
            while current is not None:
                path_tuple.append(current)
                current = path[current]
            path_tuple.reverse()
            return (distance[target], path_tuple)

        # Explore neighbors
