def shortest_path(graph, source, target):
    # Initialize the distance dictionary with infinity for all nodes except the source
    distances = {node: float('inf') for node in graph}
    distances[source] = 0

    # Initialize the path dictionary with None for all nodes
    paths = {node: None for node in graph}

    # Priority queue to hold the nodes to be visited
    queue = [(0, source)]

    while queue:
        current_distance, current_node = heapq.heappop(queue)

        # If we reached the target node, reconstruct the path and return
        if current_node == target:
            path = []
            while current_node is not None:
                path.append(current_node)
                current_node = paths[current_node]
            return (current_distance, path[::-1])

        # Skip if the distance from the source to the current node is greater than the distance found so far
        if current_distance > distances[current_node]:
            continue

        for neighbor, weight in graph[current_node]:
            distance = current_distance + weight

            # Only consider this new path if it's shorter than any previously known path
            if distance < distances[neighbor]:
                distances[neighbor] = distance
                paths[neighbor] = current_node
                heapq.heappush(queue, (distance, neighbor))

    # If we exited the loop without finding a path to the target, the target is unreachable
    return (float('inf'), None)

