    def min_distance():
        min_node = None
        min_dist = float('inf')
        for node in graph:
            if distance[node] < min_dist and node:
                min_dist = distance[node]
                min_node = node
        return min_node

    # Function to relax the edges
    def relax(node):
        for neighbor, weight in graph[node]:
            if distance[node] + weight < distance[neighbor]:
                distance[neighbor] = distance[node] + weight
                previous[neighbor] = node

    # Popping and relaxing the nodes until we reach the target or the queue is empty
    queue = list(graph.keys())
    while queue:
        current = min_distance()
        if current == target:
            break
        relax(current)
        queue.remove(current)

    if distance[target] == float('inf'):
        return float('inf'), None
    else:
        # Reconstructing the path
        path = []
        node = target
        while previous[node] is not None:
            path.append(node)
            node = previous[node]
        path.append(source)
        path.reverse()
        return distance[target], path
