from collections import defaultdict, deque
import sys

def shortest_path(graph, source, target):
    # Create a dictionary to keep track of the shortest distance from the source to each node
    shortest_dist = {node: sys.maxsize for node in graph}
    shortest_dist[source] = 0

    # The queue will store tuples of (current node, distance from source)
    queue = deque([(source, 0)])

    while queue:
        current_node, current_distance = queue.popleft()

        # If we have reached the target, we can stop
        if current_node == target:
            return (current_distance, [current_node])

        # Explore the neighbors
        for neighbor, weight in graph[current_node]:
            distance_to_neighbor = current_distance + weight

            # If we found a shorter path, update the distance and path to the neighbor
            if distance_to_neighbor < shortest_dist[neighbor]:
                shortest_dist[neighbor] = distance_to_neighbor
                # Update the path to the neighbor as well
                queue.append((neighbor, distance_to_neighbor))
                # Rebuild the path
                shortest_path_to_neighbor = [target] + [current_node] + list(reversed([neighbor for neighbor, _ in graph[current_node] if neighbor != source]))
                return (shortest_dist[neighbor], shortest_path_to_neighbor)

    # If we exited the loop without finding the target, the target is unreachable
    return (float("inf"), None)
