from collections import defaultdict
from heapq import heappush, heappop

def shortest_path(graph, source, target):
    # Dictionary to keep track of visited nodes
    visited = {}

    # Priority queue to store (distance, node) pairs
    pq = [(0, source)]

    # Dictionary to keep track of the path from the source to the current node
    path = {}

    # Dictionary to store the shortest distance to each node
    distances = {node: float('inf') for node in graph}

    distances[source] = 0

    path[source] = None
    visited[source] = True

    while pq:
        current_distance, current_node = heappop(pq)

        if current_node == target:
            path_found = []
            while current_node is not None:
                path_found.append(current_node)
                current_node = path[current_node]
            return (current_distance, path_found[::-1])

        for neighbor, weight in graph[current_node]:
            distance = current_distance + weight

            if neighbor not in visited or distance < distances[neighbor]:
                visited[neighbor] = True
                distances[neighbor] = distance
                path[neighbor] = current_node
                heappush(pq, (distance, neighbor))

    # If target is unreachable, return infinity and None
    return (float('inf'), None)

